// static
bool UnionTraits<::nearby::connections::mojom::PayloadContent::DataView, ::nearby::connections::mojom::PayloadContentPtr>::Read(
    ::nearby::connections::mojom::PayloadContent::DataView input,
    ::nearby::connections::mojom::PayloadContentPtr* output) {
  using UnionType = ::nearby::connections::mojom::PayloadContent;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kBytes: {
      ::nearby::connections::mojom::BytesPayloadPtr result_bytes;
      if (!input.ReadBytes(&result_bytes))
        return false;

      *output = UnionType::NewBytes(
          std::move(result_bytes));
      break;
    }
    case Tag::kFile: {
      ::nearby::connections::mojom::FilePayloadPtr result_file;
      if (!input.ReadFile(&result_file))
        return false;

      *output = UnionType::NewFile(
          std::move(result_file));
      break;
    }
    default:

      return false;
  }
  return true;
}

